        if r != prev+1:
            groups.append((start,prev+1)); start=r
        prev=r
    groups.append((start,prev+1))
    if len(groups)<2:
        return out
    (top,te),(bottom,be)=groups[:2]
    for k in range(min(te-top,be-bottom)):
        a,b=top+k,bottom+k
        end_a=max((c for c,v in enumerate(grid[a]) if v!=bg),default=-1)
        end_b=max((c for c,v in enumerate(grid[b]) if v!=bg),default=-1)
        # Transfer the horizontal extension from the longer row to the shorter
