 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    if not active:
        return out
    start = prev = active[0]
    for r in active[1:]:
        if r != prev + 1:
            groups.append((start, prev + 1))
            start = r
        prev = r
    groups.append((start, prev + 1))
    if len(groups) < 2:
        return out
    (a, ae), (b, be) = groups[:2]
    for k in range(min(ae - a, be - b)):
        r1, r2 = a + k, b + k
        end1 = max((c for c, v in enumerate(grid[r1]) if v != bg), default=-1)
        end2 = max((c for c, v in enumerate(grid[r2]) if v != bg), default=-1)
        if end1 > end2 + 1:
            target, end = r2, end2
        elif end2 > end1 + 1:
            target, end = r1, end1
        else:
            continue
        for c in range(end + 1, len(grid[target])):
            out[target][c] = 1
    return out


def _validate():
    # Demo 4 line extension.
    g = [[8] * 9 for _ in range(13)]
    g[1] = [4, 4, 4, 4, 4, 4, 4, 8, 8]
    g[9] = [4] * 9
    expected = [row[:] for row in g]
    expected[1][7:] = [1, 1]
    assert transform(g) == expected
    return True


if __name__ == '__main__':
    assert _validate()
    print('checks passed')
