    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(v != background for v in row)]
    if not active_rows:
        return out

    blocks = []
    start = prev = active_rows[0]
    for r in active_rows[1:]:
        if r != prev + 1:
            blocks.append((start, prev + 1))
            start = r
        prev = r
    blocks.append((start, prev + 1))
    if len(blocks) < 2:
        return out

    (a, ae), (b, be) = blocks[:2]
    height = min(ae - a, be - b)
    count_a = sum(v != background for r in range(a, a + height) for v in grid[r])
    count_b = sum(v != background for r in range(b, b + height) for v in grid[r])
    if count_a >= count_b:
        source, target = a, b
    else:
        source, target = b, a

    # Overlay the fuller motif onto its aligned, incomplete copy. New cells
    # are marked with 1; existing colors and background remain untouched.
    for k in range(height):
        sr, tr = source + k, target + k
        for c in range(min(len(grid[sr]), len(grid[tr]))):
            if grid[sr][c] != background and grid[tr][c] == background:
                out[tr][c] = 1
    return out


def _validate():
    g = [[8] * 9 for _ in range(13)]
    g[1] = [4, 4, 4, 4, 4, 4, 4, 8, 8]
    g[9] = [4] * 9
    expected = [row[:] for row in g]
    expected[1][7:] = [1, 1]
    return transform(g) == expected

if __name__ == '__main__':
    assert _validate()
    print('validation passed')
",
 "cross_profile": false
}

